{
  "platform": "host",
  "provider": "Service",
  "method": "listService",
  "data": {
    "mode": "service",
    "service": {
      "key": "developmentTasks",
      "description": "Host service for immutable Task lineage, shared context, and Agent-session bindings.",
      "access": {
        "optional": {
          "expression": "ctx.get(\"developmentTasks\")",
          "requiresUndefinedCheck": true
        },
        "hardDependency": {
          "inject": [
            "developmentTasks"
          ],
          "expression": "ctx.developmentTasks"
        }
      },
      "methods": [
        {
          "signature": "@Remote('list') list(request: DevelopmentTaskListRequest): readonly DevelopmentTaskSnapshot[]",
          "description": "Read bounded current Task projections ordered by recent activity.",
          "parameters": [
            {
              "name": "request",
              "description": "optional participant filter plus result limit."
            }
          ],
          "returns": "detached Task projections."
        },
        {
          "signature": "@Remote('get') get(request: DevelopmentTaskGetRequest): DevelopmentTaskSnapshot",
          "description": "Read one current Task projection.",
          "parameters": [
            {
              "name": "request",
              "description": "exact Task identity."
            }
          ],
          "returns": "detached current projection."
        },
        {
          "signature": "@Remote('lineage') lineage(request: DevelopmentTaskLineageRequest): DevelopmentTaskLineageSnapshot",
          "description": "Read a bounded ancestor and descendant neighborhood.",
          "parameters": [
            {
              "name": "request",
              "description": "focus Task, depths, and total result limit."
            }
          ],
          "returns": "graph Tasks and ids omitted at the requested boundary."
        },
        {
          "signature": "create(request: DevelopmentTaskCreateRequest): Promise<DevelopmentTaskSnapshot>",
          "description": "Create one Root, Fork, or Merge Task and then materialize its hidden Room.",
          "parameters": [
            {
              "name": "request",
              "description": "immutable parent relation and the new Task's context fields."
            }
          ],
          "returns": "committed Task; `runtime` is degraded when Room reconciliation fails."
        },
        {
          "signature": "@Remote('create') async createRemote(request: DevelopmentTaskCreateRequest): Promise<DevelopmentTaskCreateResult>",
          "description": "Create one Task through Remote and report hidden-Room materialization separately.",
          "parameters": [
            {
              "name": "request",
              "description": "immutable parent relation and the new Task's context fields."
            }
          ],
          "returns": "committed Task and runtime state."
        },
        {
          "signature": "@Remote('publishContext') publishContext(request: DevelopmentTaskPublishContextRequest): Promise<DevelopmentTaskSnapshot>",
          "description": "Publish explicit context that may be inherited by later Tasks.",
          "parameters": [
            {
              "name": "request",
              "description": "Task, assigned participant, text, and optional artifact URI."
            }
          ],
          "returns": "updated Task projection."
        },
        {
          "signature": "@Remote('approveObservedInterval') approveObservedInterval(request: DevelopmentTaskApproveObservedIntervalRequest): Promise<DevelopmentTaskObservedInterval>",
          "description": "Approve one exact remote binding on its Task owner; Mesh membership alone grants no observation interval. This approval attests the named source identity, not a read of its private files or its current assignment replica.",
          "parameters": [
            {
              "name": "request",
              "description": "remote Agent identity and binding epoch explicitly selected by the local owner."
            }
          ],
          "returns": "original approval or a newly committed active interval; ended identities cannot reopen."
        },
        {
          "signature": "@Remote('observedIntervals') async observedIntervals(request: DevelopmentTaskGetRequest): Promise<readonly DevelopmentTaskObservedInterval[]>",
          "description": "Read authoritative observation approvals and terminal receipts, including on a remote Task owner.",
          "parameters": [
            {
              "name": "request",
              "description": "Task whose source intervals are requested."
            }
          ],
          "returns": "committed intervals; the trusted Mesh still exposes all Task context to its members."
        },
        {
          "signature": "@Remote('observedCandidates') observedCandidates(request: DevelopmentTaskGetRequest): readonly DevelopmentTaskObservedCandidate[]",
          "description": "List replicated remote Agent bindings that the local Task owner may explicitly approve. A candidate identifies a binding, not a verified Claude request or private-file permission.",
          "parameters": [
            {
              "name": "request",
              "description": "locally owned Task whose current remote assignments are inspected."
            }
          ],
          "returns": "source identities with their replicated session labels; replication can delay discovery."
        },
        {
          "signature": "async admitObservedRemote( request: DevelopmentTaskAdmitRemoteObservedContextRequest, ): Promise<DevelopmentTaskAdmitRemoteObservedContextResult>",
          "description": "Route a filtered local observation to the remote Task owner using the current Host's Mesh identity. The caller checks local capture authorization and binding currency; the owner checks its approved interval.",
          "parameters": [
            {
              "name": "request",
              "description": "exact approved interval, source digest, and locally authorized content."
            }
          ],
          "returns": "the publication and receipt of its original durable owner admission."
        },
        {
          "signature": "acceptObservedRemote( request: DevelopmentTaskAdmitRemoteObservedContextRequest, sourceNodeId: DevelopmentNodeId, ): Promise<DevelopmentTaskAdmitRemoteObservedContextResult>",
          "description": "Admit a Mesh observation using transport-owned identity; this Host method exposes no Remote endpoint.",
          "parameters": [
            {
              "name": "request",
              "description": "wire-validated observation and owner approval reference."
            },
            {
              "name": "sourceNodeId",
              "description": "peer supplied by the Mesh dispatcher, never by the request JSON."
            }
          ],
          "returns": "the original durable receipt for a matching retry, including after interval termination."
        },
        {
          "signature": "@Remote('endObservedInterval') async endObservedInterval(request: DevelopmentTaskEndObservedIntervalRequest): Promise<DevelopmentTaskObservedReceipt>",
          "description": "End one source interval on its owner, including before an approval arrives.",
          "parameters": [
            {
              "name": "request",
              "description": "complete source identity retained before local capture stops."
            }
          ],
          "returns": "receipt for the original terminal owner event; transport failure does not prove rejection."
        },
        {
          "signature": "acceptObservedIntervalEnd( request: DevelopmentTaskEndObservedIntervalRequest, sourceNodeId: DevelopmentNodeId, ): Promise<DevelopmentTaskObservedReceipt>",
          "description": "Persist one terminal interval transition and its derived withdrawals using transport-owned source identity.",
          "parameters": [
            {
              "name": "request",
              "description": "exact interval identity; a source may end it before the owner approves it."
            },
            {
              "name": "sourceNodeId",
              "description": "authenticated source peer or the local Task owner."
            }
          ],
          "returns": "stable terminal receipt after persistence; late samples cannot reopen this identity."
        },
        {
          "signature": "openLocalContribution(grant: DevelopmentTaskLocalContributionGrant): Promise<DevelopmentTaskLocalContribution>",
          "description": "Open explicitly authorized contribution collection for one current owner-local Agent assignment.",
          "parameters": [
            {
              "name": "grant",
              "description": "exact capture, binding epoch, source permission, and finite limits retained by the source adapter."
            }
          ],
          "returns": "original durable local authority; ended captures cannot reopen."
        },
        {
          "signature": "localContributionStatus(request: { readonly grant: DevelopmentTaskLocalContributionGrant }): Promise<DevelopmentTaskLocalContribution>",
          "description": "Inspect original local capture authority after committing due expiry or binding withdrawal.",
          "parameters": [
            {
              "name": "request",
              "description": "exact original local capture permission."
            }
          ],
          "returns": "current durable authority, never a replacement capture."
        },
        {
          "signature": "admitLocalContribution(request: DevelopmentTaskLocalContributionRequest): Promise<DevelopmentTaskLocalContributionResult>",
          "description": "Admit one persisted report for an explicitly authorized local capture.",
          "parameters": [
            {
              "name": "request",
              "description": "original structured outbox sample; Task generates text and attribution."
            }
          ],
          "returns": "its original commit for exact retries, including after termination."
        },
        {
          "signature": "endLocalContribution(request: DevelopmentTaskEndLocalContributionRequest): Promise<DevelopmentTaskLocalContributionReceipt>",
          "description": "Permanently withdraw a local capture without requiring a live or still-bound source Agent.",
          "parameters": [
            {
              "name": "request",
              "description": "original grant and explicit terminal reason; unknown captures receive a tombstone."
            }
          ],
          "returns": "original durable end receipt; no pending approval can reopen the same capture."
        },
        {
          "signature": "openPeerContribution(grant: DevelopmentTaskPeerContributionGrant): Promise<DevelopmentTaskPeerContribution>",
          "description": "Approve one independent peer's exact capture and source on a local Root Task.",
          "parameters": [
            {
              "name": "grant",
              "description": "immutable authorization supplied by the authenticated local owner facade."
            }
          ],
          "returns": "original durable approval; a terminal grant or capture generation cannot reopen."
        },
        {
          "signature": "peerContributions(request: { readonly taskId?: DevelopmentTaskId }): readonly DevelopmentTaskPeerContribution[]",
          "description": "Inspect local owner contribution authority without implying current online peer authorization.",
          "parameters": [
            {
              "name": "request",
              "description": "optional local Root Task; omitted selects only locally owned Tasks."
            }
          ],
          "returns": "immutable authority derived from Task commits; callers reconcile expiry before use."
        },
        {
          "signature": "expirePeerContributions(request: { readonly taskId?: DevelopmentTaskId }): Promise<void>",
          "description": "End all due local contribution grants through the same queue as admission.",
          "parameters": [
            {
              "name": "request",
              "description": "optional locally owned Task of any origin; omitted never mutates Mesh replicas."
            }
          ],
          "returns": "after every due terminal event is durable; read consumers await this before projection."
        },
        {
          "signature": "admitPeerContribution( request: DevelopmentTaskPeerContributionRequest, authenticatedPeerId: ScopePeerId, ): Promise<DevelopmentTaskPeerContributionResult>",
          "description": "Accept one exact sample from an authenticated contributor without Room membership.",
          "parameters": [
            {
              "name": "request",
              "description": "persisted outbox sample; text and provenance remain owner-controlled."
            },
            {
              "name": "authenticatedPeerId",
              "description": "transport-owned peer identity, never a JSON assertion."
            }
          ],
          "returns": "original receipt for identical retries, including after termination; new terminal samples fail."
        },
        {
          "signature": "endPeerContribution( request: DevelopmentTaskEndPeerContributionRequest, authenticatedPeerId: ScopePeerId, ): Promise<DevelopmentTaskPeerContributionReceipt>",
          "description": "End source evidence, including a delayed approval identified by its complete grant.",
          "parameters": [
            {
              "name": "request",
              "description": "exact grant; only its owner may revoke, while its contributor may leave."
            },
            {
              "name": "authenticatedPeerId",
              "description": "local owner identity or transport-authenticated source."
            }
          ],
          "returns": "original terminal receipt; repeated termination does not advance Task revision."
        },
        {
          "signature": "admitObservedContext(request: DevelopmentTaskAdmitObservedContextRequest): Promise<DevelopmentTaskAdmitObservedContextResult>",
          "description": "Admit a caller-authorized observation for a still-current local binding. The serialized operation checks ownership and binding before looking up prior admission. Callers own capture permission and source identity; this Host method exposes no Remote endpoint.",
          "parameters": [
            {
              "name": "request",
              "description": "local Task, Agent binding interval, source digest, filtered text, and optional reader evidence."
            }
          ],
          "returns": "current Task and the original publication, after persistence for a new source.",
          "throws": [
            "for a nonlocal Task, unavailable local Agent, stale binding, invalid digest, conflicting source, or publication limits."
          ]
        },
        {
          "signature": "revokeObservedArtifact(request: DevelopmentTaskRevokeObservedArtifactRequest): Promise<DevelopmentTaskAdmitObservedContextResult>",
          "description": "Revoke a previously admitted artifact chain without requiring its Agent to remain online or bound. This Host-only method proves the original publisher, binding interval, artifact, and grant from Task history.",
          "parameters": [
            {
              "name": "request",
              "description": "terminal observation and the binding identity used by its earlier samples."
            }
          ],
          "returns": "original or newly persisted revocation publication.",
          "throws": [
            "when the chain is absent, mismatched, already ended by another source, or cannot fit its reserved event."
          ]
        },
        {
          "signature": "assignmentList(): readonly DevelopmentTaskAssignment[]",
          "description": "Read all current Agent assignments.",
          "parameters": [],
          "returns": "detached assignments ordered by participant identity."
        },
        {
          "signature": "latestAssignment(participantId: DevelopmentParticipantId): DevelopmentTaskAssignment | undefined",
          "description": "Read the most recently bound retained assignment, independently of timestamps and acknowledgements.",
          "parameters": [
            {
              "name": "participantId",
              "description": "participant whose retained bindings are considered."
            }
          ],
          "returns": "frozen latest assignment still owned by the participant, or undefined when unbound."
        },
        {
          "signature": "checkout(request: DevelopmentTaskCheckoutRequest): Promise<DevelopmentTaskCheckoutResult>",
          "description": "Bind one local online Agent session to a Task, then reconcile Rooms.",
          "parameters": [
            {
              "name": "request",
              "description": "target Task, Agent participant, and optional existing session binding."
            }
          ],
          "returns": "committed session binding, Task context, and independent Room outcomes."
        },
        {
          "signature": "clear(request: DevelopmentTaskClearRequest): Promise<void>",
          "description": "Clear one local Agent session's Task binding.",
          "parameters": [
            {
              "name": "request",
              "description": "binding identity, owning Agent participant, and optional exact checkout epoch."
            }
          ],
          "returns": "resolution after binding commit and best-effort Room leave."
        },
        {
          "signature": "acknowledge(request: DevelopmentTaskAcknowledgeRequest): Promise<DevelopmentTaskAssignment>",
          "description": "Record that one Agent session received a specific Task revision.",
          "parameters": [
            {
              "name": "request",
              "description": "binding, Agent, Task, and delivered revision."
            }
          ],
          "returns": "updated session binding."
        },
        {
          "signature": "currentContextView(taskId: DevelopmentTaskId): Promise<DevelopmentTaskContextView>",
          "description": "Capture context only after local peer expiry is durable, without changing frozen inherited history.",
          "parameters": [
            {
              "name": "taskId",
              "description": "local Task or a replica containing no active direct peer evidence."
            }
          ],
          "returns": "a detached context view captured in the owner-operation queue.",
          "throws": [
            "RUNTIME_UNAVAILABLE for active direct peer evidence in a nonowner replica; its owner must authorize the read."
          ]
        },
        {
          "signature": "contextView(taskId: DevelopmentTaskId): DevelopmentTaskContextView",
          "description": "Capture the stored Task snapshot and frozen inherited block without checking current authorization.",
          "parameters": [
            {
              "name": "taskId",
              "description": "exact Task identity."
            }
          ],
          "returns": "detached stored context; model consumers use currentContextView for current peer evidence."
        },
        {
          "signature": "@Remote('context') context(request: DevelopmentTaskGetRequest): DevelopmentTaskContextView",
          "description": "Inspect stored context for one Task through the authenticated local Remote.",
          "parameters": [
            {
              "name": "request",
              "description": "exact Task identity."
            }
          ],
          "returns": "stored Task plus its immutable inherited block; this is not a current peer authorization check."
        },
        {
          "signature": "log(): readonly DevelopmentTaskLogEntry[]",
          "description": "Read the complete Task event set for storage and Mesh replication.",
          "parameters": [],
          "returns": "immutable entries in local acceptance order."
        },
        {
          "signature": "assignmentLog(): readonly DevelopmentTaskAssignmentLogEntry[]",
          "description": "Read the complete assignment event set for storage and Mesh replication.",
          "parameters": [],
          "returns": "immutable entries in local acceptance order."
        },
        {
          "signature": "blocks(): readonly DevelopmentTaskContextBlock[]",
          "description": "Read all immutable context blocks for storage and Mesh replication.",
          "parameters": [],
          "returns": "detached content-addressed blocks."
        },
        {
          "signature": "restoreContextBlocks(blocks: readonly DevelopmentTaskContextBlock[]): void",
          "description": "Restore context blocks before events that may reference them.",
          "parameters": [
            {
              "name": "blocks",
              "description": "durable blocks whose digest must match their identity."
            }
          ]
        },
        {
          "signature": "restoreLog(candidates: readonly DevelopmentTaskLogEntry[]): void",
          "description": "Restore a durable mixed-origin Task log without rewriting it. Parent dependencies are resolved before child events. Configured capacity must retain every local live artifact grant's revocation reservation.",
          "parameters": [
            {
              "name": "candidates",
              "description": "validated persisted events."
            }
          ]
        },
        {
          "signature": "restoreAssignmentLog(entries: readonly DevelopmentTaskAssignmentLogEntry[]): void",
          "description": "Restore durable assignment events without rewriting them.",
          "parameters": [
            {
              "name": "entries",
              "description": "validated assignment events."
            }
          ]
        },
        {
          "signature": "async acceptContextReplica(block: DevelopmentTaskContextBlock): Promise<void>",
          "description": "Persist and accept one authenticated peer context block idempotently.",
          "parameters": [
            {
              "name": "block",
              "description": "wire-validated content-addressed block."
            }
          ],
          "returns": "resolution after durable acceptance."
        },
        {
          "signature": "acceptLogReplica(candidate: DevelopmentTaskLogEntry, sourceNodeId: DevelopmentNodeId): Promise<DevelopmentTaskSnapshot>",
          "description": "Accept one authenticated peer Task event, persisting it only if unseen.",
          "parameters": [
            {
              "name": "candidate",
              "description": "wire-validated event."
            },
            {
              "name": "sourceNodeId",
              "description": "authenticated peer identity."
            }
          ],
          "returns": "current Task projection."
        },
        {
          "signature": "acceptAssignmentReplica( candidate: DevelopmentTaskAssignmentLogEntry, sourceNodeId: DevelopmentNodeId, ): Promise<DevelopmentTaskAssignment | undefined>",
          "description": "Persist and append one unseen authenticated peer assignment event; exact committed retries return the current assignment.",
          "parameters": [
            {
              "name": "candidate",
              "description": "wire-validated assignment event."
            },
            {
              "name": "sourceNodeId",
              "description": "authenticated participant-home node."
            }
          ],
          "returns": "current assignment or undefined after clear."
        },
        {
          "signature": "async reconcileAllRooms(): Promise<void>",
          "description": "Ensure hidden Rooms exist for every locally owned restored Task.",
          "parameters": [],
          "returns": "resolution after all independent reconciliations settle."
        }
      ]
    },
    "referencedTypes": [
      {
        "name": "Branded",
        "declaration": "export type Branded<B extends string> = string & {\n    readonly [BRAND]: B;\n};"
      },
      {
        "name": "DevelopmentNodeId",
        "declaration": "export type DevelopmentNodeId = Branded<'DevelopmentNodeId'>;"
      },
      {
        "name": "DevelopmentParticipantId",
        "declaration": "export type DevelopmentParticipantId = Branded<'DevelopmentParticipantId'>;"
      },
      {
        "name": "DevelopmentRoomId",
        "declaration": "export type DevelopmentRoomId = Branded<'DevelopmentRoomId'>;"
      },
      {
        "name": "DevelopmentTaskAcknowledgeRequest",
        "declaration": "export interface DevelopmentTaskAcknowledgeRequest {\n    readonly bindingId: DevelopmentTaskBindingId;\n    readonly participantId: DevelopmentParticipantId;\n    readonly taskId: DevelopmentTaskId;\n    readonly revision: number;\n    readonly expectedBindingEpoch?: {\n        readonly nodeId: DevelopmentNodeId;\n        readonly seq: number;\n    };\n}"
      },
      {
        "name": "DevelopmentTaskAdmitObservedContextRequest",
        "declaration": "export interface DevelopmentTaskAdmitObservedContextRequest {\n    readonly taskId: DevelopmentTaskId;\n    readonly participantId: DevelopmentParticipantId;\n    readonly bindingId: DevelopmentTaskBindingId;\n    readonly expectedBindingEpoch: {\n        readonly nodeId: DevelopmentNodeId;\n        readonly seq: number;\n    };\n    readonly sourceId: DevelopmentTaskObservedSourceId;\n    readonly text: string;\n    readonly observation?: DevelopmentTaskOpenApiObservationIdentity & Exclude<DevelopmentTaskOpenApiObservationResult, {\n        readonly state: 'revoked';\n    }>;\n}"
      },
      {
        "name": "DevelopmentTaskAdmitObservedContextResult",
        "declaration": "export interface DevelopmentTaskAdmitObservedContextResult {\n    readonly outcome: 'published' | 'reused';\n    readonly task: DevelopmentTaskSnapshot;\n    readonly publication: DevelopmentTaskContextPublication;\n}"
      },
      {
        "name": "DevelopmentTaskAdmitRemoteObservedContextRequest",
        "declaration": "export interface DevelopmentTaskAdmitRemoteObservedContextRequest extends DevelopmentTaskAdmitObservedContextRequest {\n    readonly intervalId: DevelopmentTaskObservedIntervalId;\n}"
      },
      {
        "name": "DevelopmentTaskAdmitRemoteObservedContextResult",
        "declaration": "export interface DevelopmentTaskAdmitRemoteObservedContextResult {\n    readonly outcome: 'published' | 'reused';\n    readonly publication: DevelopmentTaskContextPublication;\n    readonly receipt: DevelopmentTaskObservedReceipt & {\n        readonly sourceId: DevelopmentTaskObservedSourceId;\n        readonly publicationId: string;\n    };\n}"
      },
      {
        "name": "DevelopmentTaskApproveObservedIntervalRequest",
        "declaration": "export type DevelopmentTaskApproveObservedIntervalRequest = DevelopmentTaskObservedIntervalIdentity;"
      },
      {
        "name": "DevelopmentTaskArtifactGrantId",
        "declaration": "export type DevelopmentTaskArtifactGrantId = Branded<'DevelopmentTaskArtifactGrantId'>;"
      },
      {
        "name": "DevelopmentTaskArtifactId",
        "declaration": "export type DevelopmentTaskArtifactId = Branded<'DevelopmentTaskArtifactId'>;"
      },
      {
        "name": "DevelopmentTaskAssignment",
        "declaration": "export interface DevelopmentTaskAssignment {\n    readonly bindingId: DevelopmentTaskBindingId;\n    readonly participantId: DevelopmentParticipantId;\n    readonly taskId: DevelopmentTaskId;\n    readonly sessionLabel?: string;\n    readonly assignedAt: number;\n    readonly acknowledgedRevision?: number;\n}"
      },
      {
        "name": "DevelopmentTaskAssignmentLogEntry",
        "declaration": "export interface DevelopmentTaskAssignmentLogEntry {\n    readonly nodeId: DevelopmentNodeId;\n    readonly seq: number;\n    readonly at: number;\n    readonly bindingId: DevelopmentTaskBindingId;\n    readonly participantId: DevelopmentParticipantId;\n    readonly change: {\n        readonly kind: 'task-bound';\n        readonly taskId: DevelopmentTaskId;\n        readonly sessionLabel?: string;\n    } | {\n        readonly kind: 'task-cleared';\n        readonly previousTaskId: DevelopmentTaskId;\n    } | {\n        readonly kind: 'context-acknowledged';\n        readonly taskId: DevelopmentTaskId;\n        readonly revision: number;\n    };\n}"
      },
      {
        "name": "DevelopmentTaskBindingId",
        "declaration": "export type DevelopmentTaskBindingId = Branded<'DevelopmentTaskBindingId'>;"
      },
      {
        "name": "DevelopmentTaskCaptureGeneration",
        "declaration": "export type DevelopmentTaskCaptureGeneration = Branded<'DevelopmentTaskCaptureGeneration'>;"
      },
      {
        "name": "DevelopmentTaskCaptureId",
        "declaration": "export type DevelopmentTaskCaptureId = Branded<'DevelopmentTaskCaptureId'>;"
      },
      {
        "name": "DevelopmentTaskCheckoutRequest",
        "declaration": "export interface DevelopmentTaskCheckoutRequest {\n    readonly taskId: DevelopmentTaskId;\n    readonly participantId: DevelopmentParticipantId;\n    readonly bindingId?: DevelopmentTaskBindingId;\n    readonly sessionLabel?: string;\n}"
      },
      {
        "name": "DevelopmentTaskCheckoutResult",
        "declaration": "export interface DevelopmentTaskCheckoutResult {\n    readonly assignment: DevelopmentTaskAssignment;\n    readonly context: DevelopmentTaskContextView;\n    readonly runtime: {\n        readonly targetJoined: boolean;\n        readonly previousLeft: boolean;\n        readonly warnings: readonly string[];\n    };\n}"
      },
      {
        "name": "DevelopmentTaskClaudeCommandObservationResult",
        "declaration": "export interface DevelopmentTaskClaudeCommandObservationResult {\n    readonly kind: 'claude-command-observation';\n    readonly version: 7;\n    readonly tool: 'Bash';\n    readonly hookEvent: 'PostToolUse' | 'PostToolUseFailure';\n    readonly fields: {\n        readonly rootIndex: number;\n        readonly command: string;\n        readonly stdout?: string;\n        readonly stderr?: string;\n        readonly interrupted?: boolean;\n        readonly error?: string;\n    };\n    readonly omissions: readonly ('stdout' | 'stderr' | 'error' | 'unsupported-tool-response')[];\n}"
      },
      {
        "name": "DevelopmentTaskClaudeStopReportResult",
        "declaration": "export interface DevelopmentTaskClaudeStopReportResult {\n    readonly kind: 'claude-stop-report';\n    readonly version: 7;\n    readonly text: string;\n    readonly sha256: string;\n    readonly stopHookActive: boolean;\n}"
      },
      {
        "name": "DevelopmentTaskClaudeWorkSource",
        "declaration": "export interface DevelopmentTaskClaudeWorkSource {\n    readonly kind: 'claude-work';\n    readonly version: 7;\n    readonly name: string;\n    readonly tools: readonly ('Write' | 'Edit')[];\n    readonly commands: readonly DevelopmentTaskCommandSelector[];\n    readonly stopReports: boolean;\n}"
      },
      {
        "name": "DevelopmentTaskClearRequest",
        "declaration": "export interface DevelopmentTaskClearRequest {\n    readonly bindingId: DevelopmentTaskBindingId;\n    readonly participantId: DevelopmentParticipantId;\n    readonly expectedBindingEpoch?: {\n        readonly nodeId: DevelopmentNodeId;\n        readonly seq: number;\n    };\n}"
      },
      {
        "name": "DevelopmentTaskCommandObservationResult",
        "declaration": "export type DevelopmentTaskCommandObservationResult = {\n    readonly kind: 'command-observation';\n    readonly version: 4;\n    readonly tool: 'Bash';\n    readonly fields: DevelopmentTaskCommandSelector;\n} & ({\n    readonly state: 'completed';\n    readonly exitCode: number | null;\n    readonly signal: string | null;\n    readonly timedOut: boolean;\n    readonly aborted: boolean;\n    readonly timeoutMs: number;\n    readonly stdout: DevelopmentTaskCommandOutput;\n    readonly stderr: DevelopmentTaskCommandOutput;\n} | {\n    readonly state: 'unavailable';\n    readonly reason: 'tool-failed' | 'completion-unavailable';\n});"
      },
      {
        "name": "DevelopmentTaskCommandOutput",
        "declaration": "export type DevelopmentTaskCommandOutput = {\n    readonly state: 'included';\n    readonly text: string;\n    readonly truncated: boolean;\n} | {\n    readonly state: 'omitted';\n    readonly reason: 'budget';\n    readonly truncated: boolean;\n};"
      },
      {
        "name": "DevelopmentTaskCommandSelector",
        "declaration": "export interface DevelopmentTaskCommandSelector {\n    readonly command: string;\n    readonly rootIndex: number;\n}"
      },
      {
        "name": "DevelopmentTaskCommandToolObservationSource",
        "declaration": "export interface DevelopmentTaskCommandToolObservationSource {\n    readonly kind: 'tool-observations';\n    readonly version: 4;\n    readonly name: string;\n    readonly tools: readonly ('Write' | 'Edit')[];\n    readonly commands: readonly DevelopmentTaskCommandSelector[];\n    readonly fileContent?: 'completed-native-file';\n    readonly initialization?: never;\n}"
      },
      {
        "name": "DevelopmentTaskCompletedFileToolObservationResult",
        "declaration": "export type DevelopmentTaskCompletedFileToolObservationResult = (Omit<Extract<DevelopmentTaskToolObservationResult, {\n    readonly tool: 'Write';\n}>, 'version'> | Omit<Extract<DevelopmentTaskToolObservationResult, {\n    readonly tool: 'Edit';\n}>, 'version'>) & {\n    readonly version: 3;\n    readonly completedFile: {\n        readonly state: 'included';\n        readonly content: string;\n        readonly sha256: string;\n    } | {\n        readonly state: 'omitted';\n        readonly reason: 'tool-failed' | 'budget' | 'unavailable';\n    };\n};"
      },
